/// V1: `(**(code **)(local + 4))(local)`: the state-function pointer stored in the local data
fn call_state(e: &mut Engine, a: u32, p: u32) -> LResult<()> {
    let _ = p;
    match a {
        0x10e90 => { mcBoulderST_Waiting_In(e)?; }
        0x10ef0 => { mcBoulderST_Waiting_Execute(e)?; }
        0x10f88 => { mcBoulderST_Creation_In(e)?; }
        0x11090 => { mcBoulderST_Creation_Execute(e)?; }
        0x11128 => { mcBoulderST_Drop_In(e)?; }
        0x11328 => { mcBoulderST_Drop_Execute(e)?; }
        _ => panic!("call through a non-state pointer {a:#x}"),
    }
    Ok(())
}
